# Search whether the known 27-cell suffix of the four center rows appears elsewhere in the grid (possibly shifted).
for rr in (14,15,16,17):
    seq=grid[rr][3:]
    hits=[]
    for r in range(30):
        for c in range(30-len(seq)+1):
            if grid[r][c:c+len(seq)]==seq:
                hits.append((r,c))
    for c in range(30):
        col=[grid[r][c] for r in range(30)]
        for s in range(30-len(seq)+1):
            if col[s:s+len(seq)]==seq:
                hits.append(('col',c,s))
    print(rr, hits)
